# Correct implementation using recursive layer approach
def solve_recursive(in_grid):
    output = [row[:] for row in in_grid]
    rows, cols = len(in_grid), len(in_grid[0])

    # Find bounding box of 5s
    min_r, max_r, min_c, max_c = rows, -1, cols, -1
    for r in range(rows):
        for c in range(cols):
            if in_grid[r][c] == 5:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    def mark_rect(r1, r2, c1, c2, fill_value):
        """Mark rectangular region with fill_value, but keep existing 5s"""
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if output[r][c] != 5:
                    output[r][c] = fill_value

    r1, r2, c1, c2 = min_r + 1, max_r - 1, min_c + 1, max_c - 1

    depth = 0
    while r1 <= r2 and c1 <= c2:
        if depth % 2 == 0:
            # Even depth (including 0): draw 5-border inside current rect
            mark_rect(r1, r2, c1, c2, 5)
        else:
            # Odd depth: fill current rect interior with 2
            mark_rect(r1, r2, c1, c2, 2)

        # Move inward
        r1 += 1
        r2 -= 1
        c1 += 1
        c2 -= 1
        depth += 1

    return output

